from __future__ import annotations

from replay_state import BatchReplayState, SyncAccumulator, audit_event, sort_events_for_sync, summarize_accumulator
from sync_models import ErpOrder, PlatformEvent, SyncBatch


def _audit(action: str, event: PlatformEvent, reason: str) -> dict[str, object]:
    return audit_event(action, event, reason)


def _create_erp_order(event: PlatformEvent) -> ErpOrder:
    return ErpOrder(
        erp_order_id=f"erp-{event.salesforce_order_id}",
        salesforce_order_id=event.salesforce_order_id,
        amount_cents=event.amount_cents,
        source_event_id=event.event_id,
        account_id=event.account_id,
    )


def _should_hold_event(event: PlatformEvent) -> bool:
    return event.channel != "OrderCreated"


def _normalize_events(events: list[PlatformEvent]) -> list[PlatformEvent]:
    return sort_events_for_sync(events)


def _build_batch(events: list[PlatformEvent], checkpoint_replay_id: int) -> SyncBatch:
    return SyncBatch(
        batch_id=f"batch-after-{checkpoint_replay_id}",
        events=tuple(_normalize_events(events)),
        checkpoint_replay_id=checkpoint_replay_id,
    )


def _process_event(
    event: PlatformEvent,
    state: BatchReplayState,
    accumulator: SyncAccumulator,
) -> None:
    state.advance(event)
    if _should_hold_event(event):
        accumulator.held(event, "unsupported_channel")
        return

    if state.seen_in_batch(event):
        accumulator.duplicate(event, "duplicate_in_batch")
        return

    state.mark_seen(event)
    order = _create_erp_order(event)
    accumulator.created(event, order)


def sync_order_events(
    events: list[PlatformEvent],
    existing_orders: list[ErpOrder],
    checkpoint_replay_id: int,
) -> dict[str, object]:
    batch = _build_batch(events, checkpoint_replay_id)
    state = BatchReplayState(existing_orders, batch.checkpoint_replay_id)
    accumulator = SyncAccumulator()

    for event in batch.ordered_events():
        _process_event(event, state, accumulator)

    return summarize_sync_run(
        accumulator.created_orders,
        accumulator.skipped_duplicates,
        accumulator.audit_events,
        state.checkpoint_id(),
    )


def summarize_sync_run(
    created_orders: list[ErpOrder],
    skipped_duplicates: list[dict[str, object]],
    audit_events: list[dict[str, object]],
    checkpoint_replay_id: int,
) -> dict[str, object]:
    accumulator = SyncAccumulator()
    accumulator.created_orders.extend(created_orders)
    accumulator.skipped_duplicates.extend(skipped_duplicates)
    accumulator.audit_events.extend(audit_events)
    return summarize_accumulator(accumulator, checkpoint_replay_id)


class MuleSoftOrderSync:
    def __init__(self, existing_orders: list[ErpOrder] | None = None, checkpoint_replay_id: int = 0) -> None:
        self.existing_orders = list(existing_orders or [])
        self.checkpoint_replay_id = checkpoint_replay_id

    def sync(self, events: list[PlatformEvent]) -> dict[str, object]:
        result = sync_order_events(events, self.existing_orders, self.checkpoint_replay_id)
        self.existing_orders.extend(result["created_orders"])  # type: ignore[arg-type]
        self.checkpoint_replay_id = int(result["checkpoint_replay_id"])
        return result

    def current_order_ids(self) -> list[str]:
        return sorted(order.salesforce_order_id for order in self.existing_orders)

    def snapshot(self) -> dict[str, object]:
        return {
            "checkpoint_replay_id": self.checkpoint_replay_id,
            "existing_order_count": len(self.existing_orders),
            "salesforce_order_ids": self.current_order_ids(),
        }


def sync_batches(
    batches: list[list[PlatformEvent]],
    existing_orders: list[ErpOrder],
    checkpoint_replay_id: int,
) -> list[dict[str, object]]:
    sync = MuleSoftOrderSync(existing_orders, checkpoint_replay_id)
    results: list[dict[str, object]] = []
    for events in batches:
        results.append(sync.sync(events))
    return results

