from __future__ import annotations

from sync_models import ErpOrder, PlatformEvent, ReplayCheckpoint, SyncAuditEvent


def audit_event(action: str, event: PlatformEvent, reason: str) -> dict[str, object]:
    return SyncAuditEvent(
        action=action,
        replay_id=event.replay_id,
        event_id=event.event_id,
        salesforce_order_id=event.salesforce_order_id,
        reason=reason,
    ).as_dict()


def order_ids_from_existing_orders(existing_orders: list[ErpOrder]) -> set[str]:
    return {order.salesforce_order_id for order in existing_orders}


def event_ids_from_existing_orders(existing_orders: list[ErpOrder]) -> set[str]:
    return {order.source_event_id for order in existing_orders}


def next_checkpoint(current: ReplayCheckpoint, events: list[PlatformEvent]) -> ReplayCheckpoint:
    checkpoint = current
    for event in events:
        checkpoint = checkpoint.advance_to(event.replay_id)
    return checkpoint


def sort_events_for_sync(events: list[PlatformEvent]) -> list[PlatformEvent]:
    return sorted(events, key=lambda event: (event.created_minute, event.replay_id, event.event_id))


class BatchReplayState:
    def __init__(self, existing_orders: list[ErpOrder], checkpoint_replay_id: int) -> None:
        self.existing_orders = list(existing_orders)
        self.checkpoint = ReplayCheckpoint(checkpoint_replay_id)
        self._seen_event_ids: set[str] = set()
        self._seen_order_ids: set[str] = set()

    def mark_seen(self, event: PlatformEvent) -> None:
        self._seen_event_ids.add(event.event_id)
        self._seen_order_ids.add(event.salesforce_order_id)

    def seen_in_batch(self, event: PlatformEvent) -> bool:
        return event.event_id in self._seen_event_ids or event.salesforce_order_id in self._seen_order_ids

    def existing_order_matches(self, event: PlatformEvent) -> bool:
        for order in self.existing_orders:
            if order.matches_event(event):
                return True
        return False

    def advance(self, event: PlatformEvent) -> None:
        self.checkpoint = self.checkpoint.advance_to(event.replay_id)

    def checkpoint_id(self) -> int:
        return self.checkpoint.replay_id

    def snapshot(self) -> dict[str, object]:
        return {
            "checkpoint_replay_id": self.checkpoint.replay_id,
            "seen_event_ids": sorted(self._seen_event_ids),
            "seen_order_ids": sorted(self._seen_order_ids),
            "existing_order_count": len(self.existing_orders),
        }


class SyncAccumulator:
    def __init__(self) -> None:
        self.created_orders: list[ErpOrder] = []
        self.skipped_duplicates: list[dict[str, object]] = []
        self.audit_events: list[dict[str, object]] = []

    def created(self, event: PlatformEvent, order: ErpOrder) -> None:
        self.created_orders.append(order)
        self.audit_events.append(audit_event("erp_order_created", event, "new_order"))

    def duplicate(self, event: PlatformEvent, reason: str) -> None:
        warning = audit_event("duplicate_skipped", event, reason)
        self.skipped_duplicates.append(warning)
        self.audit_events.append(warning)

    def held(self, event: PlatformEvent, reason: str) -> None:
        self.audit_events.append(audit_event("event_held", event, reason))

    def as_counts(self) -> dict[str, int]:
        return {
            "created_order_count": len(self.created_orders),
            "skipped_duplicate_count": len(self.skipped_duplicates),
            "audit_event_count": len(self.audit_events),
        }


def summarize_accumulator(accumulator: SyncAccumulator, checkpoint_replay_id: int) -> dict[str, object]:
    return {
        "created_order_count": len(accumulator.created_orders),
        "skipped_duplicate_count": len(accumulator.skipped_duplicates),
        "checkpoint_replay_id": checkpoint_replay_id,
        "created_orders": accumulator.created_orders,
        "skipped_duplicates": accumulator.skipped_duplicates,
        "audit_events": accumulator.audit_events,
        "audit_event_count": len(accumulator.audit_events),
    }

