from __future__ import annotations

from dataclasses import dataclass


VALID_CHANNELS = {"OrderCreated", "OrderUpdated", "OrderCancelled"}
VALID_CHECKPOINT_STATES = {"ready", "recovering", "paused"}


def _require_text(value: str, field_name: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class PlatformEvent:
    replay_id: int
    event_id: str
    salesforce_order_id: str
    account_id: str
    amount_cents: int
    created_minute: int
    channel: str = "OrderCreated"
    correlation_id: str | None = None

    def __post_init__(self) -> None:
        if self.replay_id < 0:
            raise ValueError("replay_id must be non-negative")
        _require_text(self.event_id, "event_id")
        _require_text(self.salesforce_order_id, "salesforce_order_id")
        _require_text(self.account_id, "account_id")
        if self.amount_cents <= 0:
            raise ValueError("amount_cents must be positive")
        if self.created_minute < 0:
            raise ValueError("created_minute must be non-negative")
        if self.channel not in VALID_CHANNELS:
            raise ValueError("unsupported channel")
        if self.correlation_id is not None:
            _require_text(self.correlation_id, "correlation_id")

    def business_key(self) -> str:
        return self.salesforce_order_id

    def envelope_key(self) -> str:
        return f"{self.channel}:{self.event_id}"


@dataclass(frozen=True)
class ErpOrder:
    erp_order_id: str
    salesforce_order_id: str
    amount_cents: int
    source_event_id: str
    account_id: str = "unknown-account"
    status: str = "OPEN"

    def __post_init__(self) -> None:
        _require_text(self.erp_order_id, "erp_order_id")
        _require_text(self.salesforce_order_id, "salesforce_order_id")
        if self.amount_cents <= 0:
            raise ValueError("amount_cents must be positive")
        _require_text(self.source_event_id, "source_event_id")
        _require_text(self.account_id, "account_id")
        _require_text(self.status, "status")

    def matches_event(self, event: PlatformEvent) -> bool:
        return self.salesforce_order_id == event.salesforce_order_id


@dataclass(frozen=True)
class ReplayCheckpoint:
    replay_id: int
    state: str = "ready"
    worker_id: str = "mule-worker-1"

    def __post_init__(self) -> None:
        if self.replay_id < 0:
            raise ValueError("replay_id must be non-negative")
        if self.state not in VALID_CHECKPOINT_STATES:
            raise ValueError("unsupported checkpoint state")
        _require_text(self.worker_id, "worker_id")

    def advance_to(self, replay_id: int) -> "ReplayCheckpoint":
        if replay_id < 0:
            raise ValueError("replay_id must be non-negative")
        return ReplayCheckpoint(
            replay_id=max(self.replay_id, replay_id),
            state=self.state,
            worker_id=self.worker_id,
        )


@dataclass(frozen=True)
class SyncAuditEvent:
    action: str
    replay_id: int
    event_id: str
    salesforce_order_id: str
    reason: str

    def __post_init__(self) -> None:
        _require_text(self.action, "action")
        if self.replay_id < 0:
            raise ValueError("replay_id must be non-negative")
        _require_text(self.event_id, "event_id")
        _require_text(self.salesforce_order_id, "salesforce_order_id")
        _require_text(self.reason, "reason")

    def as_dict(self) -> dict[str, object]:
        return {
            "action": self.action,
            "replay_id": self.replay_id,
            "event_id": self.event_id,
            "salesforce_order_id": self.salesforce_order_id,
            "reason": self.reason,
        }


@dataclass(frozen=True)
class SyncBatch:
    batch_id: str
    events: tuple[PlatformEvent, ...]
    checkpoint_replay_id: int

    def __post_init__(self) -> None:
        _require_text(self.batch_id, "batch_id")
        if self.checkpoint_replay_id < 0:
            raise ValueError("checkpoint_replay_id must be non-negative")

    def ordered_events(self) -> list[PlatformEvent]:
        return sorted(self.events, key=lambda event: (event.created_minute, event.replay_id, event.event_id))


def checkpoint_from_id(replay_id: int) -> ReplayCheckpoint:
    return ReplayCheckpoint(replay_id=replay_id)

