@dataclass(frozen=True)
class SyncBatch:
    batch_id: str
    events: tuple[PlatformEvent, ...]
    checkpoint_replay_id: int

    def __post_init__(self) -> None:
        _require_text(self.batch_id, "batch_id")
        if self.checkpoint_replay_id < 0:
            raise ValueError("checkpoint_replay_id must be non-negative")

    def ordered_events(self) -> list[PlatformEvent]:
        return sorted(self.events, key=lambda event: (event.created_minute, event.replay_id, event.event_id))


def checkpoint_from_id(replay_id: int) -> ReplayCheckpoint:
    return ReplayCheckpoint(replay_id=replay_id)
